mbr.copysrc:
     /* =================================================================== */
     /*                                                                     */
     /*  Documentation:                                                     */
     /*                                                                     */
     /*  Utility . . . : DSPSRC                                        */
     /*  Object  . . . : A_INSTALL  (PGM)                                   */
     /*  Source member : A_INSTALL                                          */
     /*  Source type . : CLLE                                               */
     /*  Description   : DSPSRC - Installer                                 */
     /*  Author  . . . : Thomas Raddatz   <thomas.raddatz@tools400.de>      */
     /*                                                                     */
     /* =================================================================== */
     /*                                                                     */
     /*  This software is free software, you can redistribute it and/or     */
     /*  modify it under the terms of the GNU General Public License (GPL)  */
     /*  as published by the Free Software Foundation.                      */
     /*                                                                     */
     /*  See GNU General Public License for details.                        */
     /*          http://www.opensource.org                                  */
     /*          http://www.opensource.org/licenses/gpl-license.html        */
     /*                                                                     */
     /* =================================================================== */
     /*  History:                                                           */
     /*                                                                     */
     /*  Datum       Name          Änderung                                 */
     /*  ----------  ------------  ---------------------------------------  */
     /*                                                                     */
     /* =================================================================== */
     /*   >>PRE-COMPILER<<                                                  */
     /*     >>CRTCMD<<    CRTBNDCL  PGM(QTEMP/&OB) +                        */
     /*                             SRCFILE(&SL/&SF) SRCMBR(&SM);           */
     /*     >>IMPORTANT<<                                                   */
     /*       >>PARM<<    OPTION(*EVENTF);                                  */
     /*     >>END-IMPORTANT<<                                               */
     /*     >>EXECUTE<<                                                     */
     /*     >>CMD<<       CALL   PGM(QTEMP/A_INSTALL) +                     */
     /*                          PARM('*CURRENT' '&SF' '&LI' 'GER');        */
     /*     >>CMD<<       DLTPGM PGM(QTEMP/A_INSTALL);                      */
     /*   >>END-PRE-COMPILER<<                                              */
     /* =================================================================== */
             PGM        PARM(&TGTRLS &SRCFILE &TOLIB &LNG)

             DCL        VAR(&TGTRLS   ) TYPE(*CHAR) LEN(10)
             DCL        VAR(&SRCFILE  ) TYPE(*CHAR) LEN(10)
             DCL        VAR(&TOLIB    ) TYPE(*CHAR) LEN(10)
             DCL        VAR(&LNG      ) TYPE(*CHAR) LEN( 3)

             DCL        VAR(&SRCLIB   ) TYPE(*CHAR) LEN(10)

             DCL        VAR(&PNLGRP   ) TYPE(*CHAR) LEN(10)
             DCL        VAR(&DSPF     ) TYPE(*CHAR) LEN(10)
             DCL        VAR(&CMD      ) TYPE(*CHAR) LEN(10)

             CHGVAR     VAR(&SRCLIB) VALUE(&TOLIB   )

             IF         COND(&LNG *EQ 'ENG') THEN(DO)
                CHGVAR     VAR(&PNLGRP ) VALUE('DSPSRCPE')
                CHGVAR     VAR(&DSPF   ) VALUE('DSPSRCDE')
                CHGVAR     VAR(&CMD    ) VALUE('DSPSRCE')
             ENDDO
             ELSE       CMD(DO)
                CHGVAR     VAR(&PNLGRP ) VALUE('DSPSRCPG')
                CHGVAR     VAR(&DSPF   ) VALUE('DSPSRCDG')
                CHGVAR     VAR(&CMD    ) VALUE('DSPSRCG')
             ENDDO

     /* ---------------------------------- */
     /*  Delete old objects                */
     /* ---------------------------------- */
             DLTCMD     CMD(&TOLIB/DSPSRC)
             MONMSG     MSGID(CPF2105)

             DLTPNLGRP  PNLGRP(&TOLIB/DSPSRCP)
             MONMSG     MSGID(CPF2105)

             DLTMOD     MODULE(&TOLIB/DSPSRCC)
             MONMSG     MSGID(CPF2105)

             DLTMOD     MODULE(&TOLIB/DSPSRCR1)
             MONMSG     MSGID(CPF2105)

             DLTMOD     MODULE(&TOLIB/DSPSRCR2)
             MONMSG     MSGID(CPF2105)

             DLTMOD     MODULE(&TOLIB/DSPSRCR3)
             MONMSG     MSGID(CPF2105)

             DLTF       FILE(&TOLIB/DSPSRCD)
             MONMSG     MSGID(CPF2105)

             DLTPGM     PGM(&TOLIB/DSPSRCC)
             MONMSG     MSGID(CPF2105)

         /* --------------------------------- */
         /*  DSPSRC v1.2 and before           */
         /* --------------------------------- */
             DLTPGM     PGM(&TOLIB/DSPSRCR1)
             MONMSG     MSGID(CPF2105)

             DLTPGM     PGM(&TOLIB/DSPSRCR2)
             MONMSG     MSGID(CPF2105)

             DLTPGM     PGM(&TOLIB/DSPSRCR3)
             MONMSG     MSGID(CPF2105)

     /* -------------------------------- */
     /*  Create display file             */
     /* -------------------------------- */
             CRTDSPF    FILE(&TOLIB/DSPSRCD) +
                          SRCFILE(&SRCLIB/&SRCFILE) +
                          SRCMBR(&DSPF)
             DLTSPLF    FILE(DSPSRCD  ) JOB(*) SPLNBR(*LAST)
             MONMSG     MSGID(CPF0000)

     /* -------------------------------- */
     /*  Create modules                  */
     /* -------------------------------- */
             CRTCLMOD   MODULE(&TOLIB/DSPSRCC ) +
                          SRCFILE(&SRCLIB/&SRCFILE) +
                          SRCMBR(*MODULE) +
                          DBGVIEW(*LIST) +
                          TGTRLS(&TGTRLS)
             DLTSPLF    FILE(DSPSRCC  ) JOB(*) SPLNBR(*LAST)
             MONMSG     MSGID(CPF0000)

             CRTRPGMOD  MODULE(&TOLIB/DSPSRCR1) +
                          SRCFILE(&SRCLIB/&SRCFILE) +
                          SRCMBR(*MODULE) +
                          DBGVIEW(*LIST) TRUNCNBR(*NO) +
                          TGTRLS(&TGTRLS)
             DLTSPLF    FILE(DSPSRCR1 ) JOB(*) SPLNBR(*LAST)
             MONMSG     MSGID(CPF0000)

             CRTRPGMOD  MODULE(&TOLIB/DSPSRCR2) +
                          SRCFILE(&SRCLIB/&SRCFILE) +
                          SRCMBR(*MODULE) +
                          DBGVIEW(*LIST) TRUNCNBR(*NO) +
                          TGTRLS(&TGTRLS)
             DLTSPLF    FILE(DSPSRCR2 ) JOB(*) SPLNBR(*LAST)
             MONMSG     MSGID(CPF0000)

             CRTRPGMOD  MODULE(&TOLIB/DSPSRCR3) +
                          SRCFILE(&SRCLIB/&SRCFILE) +
                          SRCMBR(*MODULE) +
                          DBGVIEW(*LIST) TRUNCNBR(*NO) +
                          TGTRLS(&TGTRLS)
             DLTSPLF    FILE(DSPSRCR3 ) JOB(*) SPLNBR(*LAST)
             MONMSG     MSGID(CPF0000)

     /* -------------------------------- */
     /*  Create programs                 */
     /* -------------------------------- */
             CRTPGM     PGM(&TOLIB/DSPSRCC) +
                        MODULE(&TOLIB/DSPSRCC   +
                               &TOLIB/DSPSRCR1  +
                               &TOLIB/DSPSRCR2  +
                               &TOLIB/DSPSRCR3) +
                          ACTGRP(*NEW) +
                          DETAIL(*BASIC) +
                          TGTRLS(&TGTRLS)
             DLTSPLF    FILE(DSPSRCC) JOB(*) SPLNBR(*LAST)
             MONMSG     MSGID(CPF0000)

     /* -------------------------------- */
     /*  Create panel groups             */
     /* -------------------------------- */
             CRTPNLGRP  PNLGRP(&TOLIB/DSPSRCP) +
                          SRCFILE(&SRCLIB/&SRCFILE) +
                          SRCMBR(&PNLGRP)
             DLTSPLF    FILE(DSPSRCP  ) JOB(*) SPLNBR(*LAST)
             MONMSG     MSGID(CPF0000)

     /* -------------------------------- */
     /*  Create commands                 */
     /* -------------------------------- */
             CRTCMD     CMD(&TOLIB/DSPSRC) PGM(&TOLIB/DSPSRCC) +
                          SRCFILE(&SRCLIB/&SRCFILE) +
                          SRCMBR(&CMD) +
                          HLPPNLGRP(&TOLIB/DSPSRCP) HLPID(DSPSRC)
             DLTSPLF    FILE(&CMD     ) JOB(*) SPLNBR(*LAST)
             MONMSG     MSGID(CPF0000)

     /* -------------------------------- */
     /*  Delete obsolete objects         */
     /* -------------------------------- */
             DLTMOD     MODULE(&TOLIB/DSPSRCC)
             DLTMOD     MODULE(&TOLIB/DSPSRCR1)
             DLTMOD     MODULE(&TOLIB/DSPSRCR2)
             DLTMOD     MODULE(&TOLIB/DSPSRCR3)

             ENDPGM

/* =================================================================== */
/*                                                                     */
/*  Kurzdokumentation :                                                */
/*                                                                     */
/*  Bereich . . . : DSPSRC                                             */
/*  Objekt  . . . : DSPSRCC                                            */
/*  Beschreibung  : Tool: DSPSRC     (Display Source Code)             */
/*  Author  . . . : Thomas Raddatz   <thomas.raddatz@tools400.de>      */
/*  Datum . . . . : 25.07.2001                                         */
/*                                                                     */
/* =================================================================== */
/*                                                                     */
/*  This software is free software, you can redistribute it and/or     */
/*  modify it under the terms of the GNU General Public License (GPL)  */
/*  as published by the Free Software Foundation.                      */
/*                                                                     */
/*  See GNU General Public License for details.                        */
/*          http://www.opensource.org                                  */
/*          http://www.opensource.org/licenses/gpl-license.html        */
/*                                                                     */
/* =================================================================== */
/*  History:                                                           */
/*                                                                     */
/*  Datum       Name          Änderung                                 */
/*  ----------  ------------  ---------------------------------------  */
/*                                                                     */
/* =================================================================== */
/* >>PRE-COMPILER<<                                                    */
/*   >>CRTCMD<< CRTCLMOD     MODULE(&LI/&OB) +                         */
/*                           SRCFILE(&SL/&SF) +                        */
/*                           SRCMBR(&SM);                              */
/*   >>COMPILE<<                                                       */
/*     >>PARM<< DBGVIEW(*LIST);                                        */
/*     >>PARM<< OPTION(*EVENTF);                                       */
/*   >>END-COMPILE<<                                                   */
/*   >>EXECUTE<<                                                       */
/*   >>CMD<<    CRTPGM       PGM(&LI/DSPSRCC   )  +                    */
/*                           MODULE(&LI/DSPSRCR1  +                    */
/*                                  &LI/DSPSRCR2  +                    */
/*                                  &LI/DSPSRCR3) +                    */
/*                           ENTMOD(&LI/DSPSRCC)  +                    */
/*                           ACTGRP(*NEW) +                            */
/*                           DETAIL(*BASIC);                           */
/* >>END-PRE-COMPILER<<                                                */
/* =================================================================== */
/*                                                                     */
/*  Bei einer Erweiterung des Parameters OBJTYPE, bitte auch im        */
/*  CL-Programm die Variable &TYPAVAIL entsprechend ändern.            */
/*  Max. sind 10 Typen möglich. Danach muß die auch die Länge          */
/*  von &TYPAVAIL sowie die Abfrage auf 100 geändert werden.           */
/*                                                                     */
/* =================================================================== */
             PGM        PARM(&OBNMLB  +
                             &OBJTYPE +
                             &DSPMDL  )

             DCL        VAR(&OBNMLB  ) TYPE(*CHAR) LEN(20)
             DCL        VAR(&OBJTYPE ) TYPE(*CHAR) LEN(10)
             DCL        VAR(&DSPMDL  ) TYPE(*CHAR) LEN( 1)

             DCL        VAR(&PGMI0100  ) TYPE(*CHAR) LEN(161)
             DCL        VAR(&PGMILEN   ) TYPE(*CHAR) LEN(  4)
             DCL        VAR(&PGMIFMT   ) TYPE(*CHAR) LEN(  8)
             DCL        VAR(&PGMINAME  ) TYPE(*CHAR) LEN( 20)
             DCL        VAR(&PGMIPGMTYP) TYPE(*CHAR) LEN(  1)
             DCL        VAR(&APIERROR  ) TYPE(*CHAR) LEN(  8)

             DCL        VAR(&OBNM    ) TYPE(*CHAR) LEN(10)
             DCL        VAR(&OBLB    ) TYPE(*CHAR) LEN(10)
             DCL        VAR(&QSRC    ) TYPE(*CHAR) LEN(20)
             DCL        VAR(&SRCF    ) TYPE(*CHAR) LEN(10)
             DCL        VAR(&SRCL    ) TYPE(*CHAR) LEN(10)
             DCL        VAR(&SRCM    ) TYPE(*CHAR) LEN(10)
             DCL        VAR(&RCD     ) TYPE(*CHAR) LEN(10)
             DCL        VAR(&STRPOS  ) TYPE(*DEC ) LEN(5 0)
             DCL        VAR(&LENAVAIL) TYPE(*DEC ) LEN(5 0) +
                        VALUE(100)
             DCL        VAR(&TYPAVAIL) TYPE(*CHAR) LEN(100) +
                        VALUE('*CMD      +
                               *FILE     +
                               *MODULE   +
                               *PGM      +
                               *SRVPGM   +
                               *TBL      ')

/* Fehlerbehandlung     */
             DCL        VAR(&ERROR)      TYPE(*LGL) +
                          VALUE('0')
             DCL        VAR(&TRUE)       TYPE(*LGL) +
                          VALUE('1')
             DCL        VAR(&FALSE)      TYPE(*LGL) +
                          VALUE('0')
             DCL        VAR(&ERRMSGKEY)  TYPE(*CHAR) LEN(4)

             DCL        VAR(&ERRMSGTYP)  TYPE(*CHAR) LEN(10) +
                          VALUE('*DIAG')
             DCL        VAR(&ERRNBRTYP)  TYPE(*CHAR) LEN(4) +
                          VALUE(X'00000001')
             DCL        VAR(&ERRPGMMSGQ) TYPE(*CHAR) LEN(10) +
                          VALUE('*')
             DCL        VAR(&ERRSTKCTR)  TYPE(*CHAR) LEN(4) +
                          VALUE(X'00000001')
             DCL        VAR(&ERRCODE  )  TYPE(*CHAR) LEN(4) +
                          VALUE(X'00000000')

/* Sende alle Fehler zur Error Handling Routine */
             MONMSG     MSGID(CPF0000) EXEC(GOTO CMDLBL(ERROR))

             CHGVAR     VAR(&ERROR    ) VALUE(&FALSE)

 /* -------------------------------------------------------------- */
 /*  Los geht's                                                    */
 /* -------------------------------------------------------------- */

             CHGVAR     VAR(&OBNM) VALUE(%SST(&OBNMLB 1 10))
             CHGVAR     VAR(&OBLB) VALUE(%SST(&OBNMLB 11 10))

 /* Objekttyp ist *SERACH     */
             IF         COND(&OBJTYPE *EQ *SEARCH) THEN(DO)
              CHGVAR     VAR(&STRPOS) VALUE(1)
 SearchLoop:
              CHGVAR     VAR(&OBJTYPE) +
                         VALUE(%SST(&TYPAVAIL &STRPOS 10))
              CHKOBJ     OBJ(&OBLB/&OBNM) OBJTYPE(&OBJTYPE)
              MONMSG     MSGID(CPF0000) EXEC(DO)
               CHGVAR     VAR(&STRPOS) VALUE(&STRPOS +10)
               IF         COND(&STRPOS *LE &LENAVAIL) THEN(DO)
                GOTO       CMDLBL(SearchLoop)
               ENDDO
               ELSE       CMD(DO)
                SNDPGMMSG  MSGID(CPF9897) MSGF(*LIBL/QCPFMSG) +
                           MSGDTA('Objekt' *BCAT &OBNM *BCAT 'vom Typ +
                           *SEARCH nicht gefunden.') TOPGMQ(*PRV +
                           (*)) MSGTYPE(*ESCAPE)
               ENDDO
              ENDDO

             ENDDO
             ELSE       CMD(DO)
 /* Objekttyp wurde angegeben */
             ENDDO

             RTVOBJD    OBJ(&OBLB/&OBNM) OBJTYPE(&OBJTYPE) +
                          SRCF(&SRCF) +
                          SRCFLIB(&SRCL) SRCMBR(&SRCM)

             CHGVAR     VAR(&PGMIPGMTYP) VALUE(' ')

             IF         COND(&OBJTYPE *EQ '*PGM') THEN(DO)
               CHGVAR     VAR(&PGMI0100)           VALUE(' ')
               CHGVAR     VAR(%BIN(&PGMILEN 1 4))  VALUE(161)
               CHGVAR     VAR(&PGMIFMT )           VALUE('PGMI0100')
               CHGVAR     VAR(&PGMINAME)           VALUE(&OBNM *CAT &OBLB)
               CHGVAR     VAR(%BIN(&APIERROR 1 4)) VALUE(  0)
               CHGVAR     VAR(%BIN(&APIERROR 5 4)) VALUE(  0)

               CALL       PGM(QCLRPGMI) PARM(&PGMI0100 +
                                             &PGMILEN  +
                                             &PGMIFMT  +
                                             &PGMINAME +
                                             &APIERROR )

               /* ------------------------------------- */
               /*  Type of program:                     */
               /*    " " - OPM program                  */
               /*    "B" - ILE program                  */
               /* ------------------------------------- */
               CHGVAR     VAR(&PGMIPGMTYP) VALUE(%SST(&PGMI0100 161 1))
             ENDDO

             IF         COND(&OBJTYPE *EQ '*SRVPGM') THEN(DO)
               CHGVAR     VAR(&PGMIPGMTYP) VALUE('B')
             ENDDO

             IF         COND(&PGMIPGMTYP *EQ 'B') THEN(DO)
              CALLPRC    PRC(DSPSRCR2) PARM(&OBNMLB  +
                                            &OBJTYPE +
                                            &DSPMDL  +
                                            &QSRC    +
                                            &SRCM    +
                                            &RCD)
              IF         COND(&RCD *EQ ' ') THEN(DO)
               CHGVAR     VAR(&SRCF) VALUE(%SST(&QSRC   1 10))
               CHGVAR     VAR(&SRCL) VALUE(%SST(&QSRC   11 10))
              ENDDO
              ELSE       CMD(DO)
               /* Abbruch durch Benutzer */
               GOTO       CMDLBL(ENDE)
              ENDDO
             ENDDO

             CHKOBJ     OBJ(&SRCL/&SRCF) OBJTYPE(*FILE) MBR(&SRCM) +
                          AUT(*USE)
             MONMSG     MSGID(CPF0000) EXEC(DO)
              SNDPGMMSG  MSG('Quellenteildatei' *BCAT &SRCM *TCAT ', +
                         Datei' *BCAT &SRCF *TCAT ', Bibliothek' +
                         *BCAT &SRCL *BCAT 'nicht gefunden.')
              GOTO       CMDLBL(ENDE)
             ENDDO

             STRSEU     SRCFILE(&SRCL/&SRCF) SRCMBR(&SRCM) OPTION(5)

 /* -------------------------------------------------------------- */
 /*  Programm beenden                                              */
 /* -------------------------------------------------------------- */

ENDE:
             DLTOVR     FILE(*ALL)
             MONMSG     MSGID(CPF0000)

             RCLRSC     LVL(*)

/* -------------------------------------------------------------- */
/*    Fehler aufgetreten ?                                        */
/* -------------------------------------------------------------- */

             IF         COND(&ERROR) THEN(DO)
               /* Sende letzte *ESCAPE nochmals   */
               CALL       PGM(QMHRSNEM) PARM(&ERRMSGKEY &ERRCODE)
               MONMSG     MSGID(CPF0000)
             ENDDO

             RETURN

/* ---------------- */
/* Nachrichten      */
/* weiterreichen    */
/* ---------------- */

 ERROR:
             IF         COND(&ERROR) THEN(GOTO CMDLBL(ENDE))
             ELSE       CHGVAR     VAR(&ERROR) VALUE(&TRUE)

/* Verschiebe alle *DIAG Nachrichten zur             */
/* vorangegangenen Programmwarteschlange             */
             CALL       PGM(QMHMOVPM) PARM(&ERRMSGKEY &ERRMSGTYP +
                          &ERRNBRTYP &ERRPGMMSGQ &ERRSTKCTR &ERRCODE)

             GOTO       CMDLBL(ENDE)

             ENDPGM

/* =================================================================== */
/*                                                                     */
/*  Kurzdokumentation :                                                */
/*                                                                     */
/*  Bereich . . . : DSPSRC                                             */
/*  Objekt  . . . : DSPSRCE                                            */
/*  Beschreibung  : Tool: DSPSRC     (Display Source Code) Eng         */
/*  Author  . . . : Thomas Raddatz   <thomas.raddatz@tools400.de>      */
/*  Datum . . . . : 03.06.2002                                         */
/*                                                                     */
/* =================================================================== */
/*                                                                     */
/*  This software is free software, you can redistribute it and/or     */
/*  modify it under the terms of the GNU General Public License (GPL)  */
/*  as published by the Free Software Foundation.                      */
/*                                                                     */
/*  See GNU General Public License for details.                        */
/*          http://www.opensource.org                                  */
/*          http://www.opensource.org/licenses/gpl-license.html        */
/*                                                                     */
/* =================================================================== */
/*  History:                                                           */
/*                                                                     */
/*  Datum       Name          Änderung                                 */
/*  ----------  ------------  ---------------------------------------  */
/*                                                                     */
/* =================================================================== */
/* >>PRE-COMPILER<<                                                    */
/*                                                                     */
/*   >>CRTCMD<< CRTCMD       CMD(&LI/DSPSRC) +                         */
/*                           SRCFILE(&SL/&SF) +                        */
/*                           SRCMBR(&SM);                              */
/*                                                                     */
/*   >>COMPILE<<                                                       */
/*     >>PARM<< PGM(*LIBL/DSPSRCC);                                    */
/*     >>PARM<< HLPPNLGRP(*LIBL/DSPSRCP);                              */
/*     >>PARM<< HLPID(DSPSRC);                                         */
/*   >>END-COMPILE<<                                                   */
/*                                                                     */
/*   >>EXECUTE<<                                                       */
/*                                                                     */
/* >>END-PRE-COMPILER<<                                                */
/* =================================================================== */
/*                                                                     */
/*  Bei einer Erweiterung des Parameters OBJTYPE, bitte auch im        */
/*  CL-Programm die Variable &TYPAVAIL entsprechend ändern.            */
/*  Max. sind 10 Typen möglich. Danach muß die auch die Länge          */
/*  von &TYPAVAIL sowie die Abfrage auf 100 geändert werden.           */
/*                                                                     */
/* =================================================================== */

             CMD        PROMPT('Display Source Code')

             PARM       KWD(OBJ) TYPE(QUAL1)     +
                          MIN(1)                 +
                          PROMPT('Object')

             PARM       KWD(OBJTYPE) TYPE(*CHAR) +
                          LEN(10)                +
                          RSTD(*YES)             +
                          DFT(*SEARCH)           +
                          VALUES(*SEARCH         +
                                 *CMD            +
                                 *FILE           +
                                 *MODULE         +
                                 *PGM            +
                                 *SRVPGM         +
                                 *TBL            +
                                 )               +
                          PROMPT('Object type')

             PARM       KWD(DSPMOD) TYPE(*CHAR)  +
                          LEN(1)                 +
                          RSTD(*YES)             +
                          DFT(*NO)               +
                          SPCVAL((*YES 1)        +
                                 (*NO  0))       +
                          PMTCTL(*PMTRQS)        +
                          PROMPT('Display ILE module list')

 QUAL1:      QUAL       TYPE(*NAME) LEN(10) MIN(1)
             QUAL       TYPE(*NAME) LEN(10) DFT(*LIBL) +
                          SPCVAL((*LIBL) (*CURLIB)) +
                          PROMPT('Library')

/* =================================================================== */
/*                                                                     */
/*  Kurzdokumentation :                                                */
/*                                                                     */
/*  Bereich . . . : DSPSRC                                             */
/*  Objekt  . . . : DSPSRCG                                            */
/*  Beschreibung  : Tool: DSPSRC     (Display Source Code) Ger         */
/*  Author  . . . : Thomas Raddatz   <thomas.raddatz@tools400.de>      */
/*  Datum . . . . : 25.07.2001                                         */
/*                                                                     */
/* =================================================================== */
/*                                                                     */
/*  This software is free software, you can redistribute it and/or     */
/*  modify it under the terms of the GNU General Public License (GPL)  */
/*  as published by the Free Software Foundation.                      */
/*                                                                     */
/*  See GNU General Public License for details.                        */
/*          http://www.opensource.org                                  */
/*          http://www.opensource.org/licenses/gpl-license.html        */
/*                                                                     */
/* =================================================================== */
/*  History:                                                           */
/*                                                                     */
/*  Datum       Name          Änderung                                 */
/*  ----------  ------------  ---------------------------------------  */
/*                                                                     */
/* =================================================================== */
/* >>PRE-COMPILER<<                                                    */
/*                                                                     */
/*   >>CRTCMD<< CRTCMD       CMD(&LI/DSPSRC) +                         */
/*                           SRCFILE(&SL/&SF) +                        */
/*                           SRCMBR(&SM);                              */
/*                                                                     */
/*   >>COMPILE<<                                                       */
/*     >>PARM<< PGM(*LIBL/DSPSRCC);                                    */
/*     >>PARM<< HLPPNLGRP(*LIBL/DSPSRCP);                              */
/*     >>PARM<< HLPID(DSPSRC);                                         */
/*   >>END-COMPILE<<                                                   */
/*                                                                     */
/*   >>EXECUTE<<                                                       */
/*                                                                     */
/* >>END-PRE-COMPILER<<                                                */
/* =================================================================== */
/*                                                                     */
/*  Bei einer Erweiterung des Parameters OBJTYPE, bitte auch im        */
/*  CL-Programm die Variable &TYPAVAIL entsprechend ändern.            */
/*  Max. sind 10 Typen möglich. Danach muß die auch die Länge          */
/*  von &TYPAVAIL sowie die Abfrage auf 100 geändert werden.           */
/*                                                                     */
/* =================================================================== */

             CMD        PROMPT('Quellenteildatei anzeigen')

             PARM       KWD(OBJ) TYPE(QUAL1)     +
                          MIN(1)                 +
                          PROMPT('Objekt')

             PARM       KWD(OBJTYPE) TYPE(*CHAR) +
                          LEN(10)                +
                          RSTD(*YES)             +
                          DFT(*SEARCH)           +
                          VALUES(*SEARCH         +
                                 *CMD            +
                                 *FILE           +
                                 *MODULE         +
                                 *PGM            +
                                 *SRVPGM         +
                                 *TBL            +
                                 )               +
                          PROMPT('Objektart')

             PARM       KWD(DSPMOD) TYPE(*CHAR)  +
                          LEN(1)                 +
                          RSTD(*YES)             +
                          DFT(*NO)               +
                          SPCVAL((*YES 1)        +
                                 (*NO  0))       +
                          PMTCTL(*PMTRQS)        +
                          PROMPT('ILE-Module anzeigen')

 QUAL1:      QUAL       TYPE(*NAME) LEN(10) MIN(1)
             QUAL       TYPE(*NAME) LEN(10) DFT(*LIBL) +
                          SPCVAL((*LIBL) (*CURLIB)) +
                          PROMPT('Bibliothek')
